package tv.managealltv.player.core.protocol

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.JsonClassDiscriminator

/** packages/protocol/src/device.ts `DeviceInfo`: hardware and software facts reported when pairing. */
@Serializable
data class DeviceInfo(
    /** Random UUID generated by the app on first launch and kept for its lifetime. */
    val hardwareId: String,
    val manufacturer: String,
    val model: String,
    val androidVersion: String,
    val sdkInt: Int,
    val appVersionName: String,
    val appVersionCode: Int,
    val screenWidth: Int,
    val screenHeight: Int,
    val freeStorageBytes: Long,
    val totalStorageBytes: Long,
    /** MIME types the device can decode, e.g. "video/avc". */
    val videoDecoders: List<String>,
)

/** POST /api/device/v1/pair */
@Serializable
data class PairRequest(val device: DeviceInfo)

@Serializable
data class PairResponse(
    /** Six digits, shown large on the TV and typed into the panel. */
    val pairingCode: String,
    /** Secret only the device knows; used to poll for the result. */
    val pairingSecret: String,
    /** ISO-8601 timestamp. */
    val expiresAt: String,
    val pollIntervalSec: Int,
)

/** POST /api/device/v1/pair/poll */
@Serializable
data class PairPollRequest(val pairingSecret: String)

@Serializable
@JsonClassDiscriminator("status")
sealed interface PairPollResponse {
    @Serializable
    @SerialName("pending")
    data object Pending : PairPollResponse

    @Serializable
    @SerialName("paired")
    data class Paired(
        val deviceId: String,
        /** Long-lived bearer token. Delivered exactly once. */
        val deviceToken: String,
        val deviceName: String,
    ) : PairPollResponse

    @Serializable
    @SerialName("expired")
    data object Expired : PairPollResponse
}

/** packages/protocol/src/device.ts `SyncState`. */
@Serializable
enum class SyncState {
    @SerialName("idle")
    IDLE,

    @SerialName("downloading")
    DOWNLOADING,

    @SerialName("error")
    ERROR,
}

/** Periodic report from the device (WebSocket "status" message or POST /api/device/v1/status). */
@Serializable
data class DeviceStatus(
    /** Manifest version currently applied on the device, null before the first sync. */
    val manifestVersion: Int?,
    val activePlaylistId: String?,
    val currentMediaId: String?,
    val syncState: SyncState,
    val syncFilesDone: Int,
    val syncFilesTotal: Int,
    val syncBytesDone: Long,
    val syncBytesTotal: Long,
    /** At most [MAX_MESSAGE_LENGTH] characters. */
    val lastError: String?,
    val freeStorageBytes: Long,
    val uptimeSec: Long,
    val appVersionName: String,
    val appVersionCode: Int,
    /** Current media volume 0-100, null if unknown. */
    val volume: Int?,
    /** "Display over other apps" permission granted (needed to come to front on wake). */
    val overlayPermission: Boolean,
    /** App is provisioned as Device Owner (launcher lock, silent updates, reboot). */
    val deviceOwner: Boolean,
) {
    companion object {
        /** Limit of `lastError` and command result messages in the Zod schemas. */
        const val MAX_MESSAGE_LENGTH: Int = 1000
    }
}

/** Response to POST /api/device/v1/status */
@Serializable
data class StatusAck(
    /** Latest manifest version on the server; the device fetches the manifest if it differs. */
    val manifestVersion: Int,
)

/** POST /api/device/v1/commands/:id/result */
@Serializable
data class CommandResult(
    val ok: Boolean,
    /** At most [DeviceStatus.MAX_MESSAGE_LENGTH] characters; shown in the panel (Turkish). */
    val message: String?,
)
